const fs = require("fs/promises");
const { createCrossmint, CrossmintWallets } = require("@crossmint/wallets-sdk");

const OUTPUT_PATH = "/home/user/wallet_debug_result.json";
const CHAIN = "base-sepolia";
const WALLET_TYPE = "smart";

async function writeResult(result) {
  await fs.writeFile(OUTPUT_PATH, `${JSON.stringify(result, null, 2)}\n`);
}

async function main() {
  const result = { chain: CHAIN, type: WALLET_TYPE };

  try {
    const apiKey = process.env.CROSSMINT_API_KEY;
    if (!apiKey) {
      throw new Error("CROSSMINT_API_KEY is required");
    }

    const serverSecret = process.env.CROSSMINT_SERVER_SECRET;
    if (!serverSecret) {
      throw new Error("CROSSMINT_SERVER_SECRET is required for server recovery");
    }

    const crossmint = createCrossmint({ apiKey });
    const wallets = CrossmintWallets.from(crossmint);

    const wallet = await wallets.createWallet({
      chain: CHAIN,
      owner: `userId:wallet-debug-${Date.now()}`,
      recovery: {
        type: "server",
        secret: serverSecret,
      },
    });

    result.address = wallet.address;
  } catch (error) {
    result.error = error instanceof Error ? error.message : String(error);
  }

  await writeResult(result);
}

main().catch(async (error) => {
  const fallback = {
    chain: CHAIN,
    type: WALLET_TYPE,
    error: error instanceof Error ? error.message : String(error),
  };

  try {
    await writeResult(fallback);
  } catch (writeError) {
    console.error("Failed to write wallet_debug_result.json", writeError);
  }
});
